import{_ as a,o as e,c as r,ag as o}from"./chunks/framework.D64lb950.js";const b=JSON.parse('{"title":"成长思考","description":"","frontmatter":{"title":"成长思考"},"headers":[],"relativePath":"categories/growth-thinking.md","filePath":"categories/growth-thinking.md","lastUpdated":1778083677000}'),d={name:"categories/growth-thinking.md"};function i(h,t,l,s,n,p){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="🎯-成长思考" tabindex="-1">🎯 成长思考 <a class="header-anchor" href="#🎯-成长思考" aria-label="Permalink to &quot;🎯 成长思考&quot;">​</a></h1><p>关于职业发展、学习方法、效率提升的思考，记录个人成长历程。</p><h2 id="学习规划" tabindex="-1">学习规划 <a class="header-anchor" href="#学习规划" aria-label="Permalink to &quot;学习规划&quot;">​</a></h2><h3 id="我的-2026-年学习计划" tabindex="-1"><a href="/my-blog/posts/2026-learning-plan">我的 2026 年学习计划</a> <a class="header-anchor" href="#我的-2026-年学习计划" aria-label="Permalink to &quot;[我的 2026 年学习计划](/posts/2026-learning-plan)&quot;">​</a></h3><p>新的一年，给自己定下学习目标。技术学习包括 Vue 3 生态深入、TypeScript 类型编程、Vite/Webpack 原理、Nest.js 框架、PostgreSQL/Redis、Docker 容器化、AI 应用开发、Rust 入门。读书计划涵盖技术书籍和非技术书籍。项目实践包括博客系统优化、工具库封装、开源贡献。</p><h2 id="读书笔记" tabindex="-1">读书笔记 <a class="header-anchor" href="#读书笔记" aria-label="Permalink to &quot;读书笔记&quot;">​</a></h2><h3 id="《从0到1》读书笔记" tabindex="-1"><a href="/my-blog/posts/zero-to-one-review">《从0到1》读书笔记</a> <a class="header-anchor" href="#《从0到1》读书笔记" aria-label="Permalink to &quot;[《从0到1》读书笔记](/posts/zero-to-one-review)&quot;">​</a></h3><p>彼得·蒂尔的经典之作，探讨如何创造新事物而非复制已有模式。核心观点：竞争是失败者的游戏，真正有价值的企业必须实现从0到1的跨越。书中详细阐述了垄断的力量、幂次法则、秘密的价值、初创企业的七大问题。这本书改变了我对创业、竞争和未来的看法。</p><h3 id="《穷爸爸富爸爸》读书笔记" tabindex="-1"><a href="/my-blog/posts/rich-dad-poor-dad-review">《穷爸爸富爸爸》读书笔记</a> <a class="header-anchor" href="#《穷爸爸富爸爸》读书笔记" aria-label="Permalink to &quot;[《穷爸爸富爸爸》读书笔记](/posts/rich-dad-poor-dad-review)&quot;">​</a></h3><p>这本书改变了我对金钱和财富的认知方式。核心观点是区分资产与负债：资产能把钱放进你口袋，负债把钱从你口袋拿走。文章详细分析了两个爸爸的不同思维模式、现金流差异、六课核心内容、克服困难的五个障碍，以及我个人的财务自由行动计划。</p><p><strong>核心认知转变：</strong></p><table tabindex="0"><thead><tr><th>旧认知</th><th>新认知</th></tr></thead><tbody><tr><td>高收入 = 富人</td><td>高资产 = 富人</td></tr><tr><td>房子 = 资产</td><td>现金流决定资产属性</td></tr><tr><td>工作稳定 = 安全</td><td>财务自由 = 安全</td></tr><tr><td>风险 = 危险</td><td>风险 = 机会的代价</td></tr></tbody></table><h2 id="随笔" tabindex="-1">随笔 <a class="header-anchor" href="#随笔" aria-label="Permalink to &quot;随笔&quot;">​</a></h2><h3 id="欢迎来到霄鸿臻的博客" tabindex="-1"><a href="/my-blog/posts/hello-world">欢迎来到霄鸿臻的博客</a> <a class="header-anchor" href="#欢迎来到霄鸿臻的博客" aria-label="Permalink to &quot;[欢迎来到霄鸿臻的博客](/posts/hello-world)&quot;">​</a></h3><p>第一篇博客文章，介绍博客的技术选型和功能展示，说明未来将分享技术学习笔记、项目实战经验和个人成长思考。</p><hr><blockquote><p>学习是一个持续的过程，保持好奇心，不断探索新的领域。财商教育是一生的功课，从今天开始行动。</p></blockquote>',17)])])}const u=a(d,[["render",i]]);export{b as __pageData,u as default};
